package quality

import (
	"fmt"
	"path"
	"regexp"
	"strings"
)

// The defaults leave out what is not the project's own production code. They
// are language-neutral conventions, and every one can be switched off with
// ExcludeConfig.

func defaultExcludedDirs() []string {
	return []string{"vendor", "node_modules", "third_party", "testdata", "tests", "test", "spec", "__tests__"}
}

// defaultExcludedFiles are matched against a file's base name.
func defaultExcludedFiles() []string {
	return []string{
		"*_test.go", "test_*.py", "*_test.py",
		"*.test.ts", "*.spec.ts", "*.test.tsx", "*.spec.tsx",
		"*.test.js", "*.spec.js", "*.test.jsx", "*.spec.jsx",
	}
}

// generatedMarkers, lower-cased, mark a generated file when one is in its first
// generatedLines lines.
func generatedMarkers() []string {
	return []string{"code generated", "@generated", "do not edit", "autogenerated"}
}

const generatedLines = 10

// ExcludeConfig says what is left out of measurement beyond git's own ignores.
type ExcludeConfig struct {
	// Exclude are globs of further paths to leave out.
	Exclude []string
	// Include are globs of paths to measure although a default leaves them out.
	Include []string
	// NoDefaults switches the built-in exclusions off.
	NoDefaults bool
}

// Excluder decides which paths are left out. The zero value applies the
// defaults only.
type Excluder struct {
	cfg     ExcludeConfig
	exclude []*regexp.Regexp
	include []*regexp.Regexp
}

// NewExcluder compiles cfg's globs; a glob that is not valid is an error.
func NewExcluder(cfg ExcludeConfig) (Excluder, error) {
	ex := Excluder{cfg: cfg}
	var err error
	if ex.exclude, err = compileGlobs(cfg.Exclude); err != nil {
		return Excluder{}, err
	}
	if ex.include, err = compileGlobs(cfg.Include); err != nil {
		return Excluder{}, err
	}
	return ex, nil
}

// ValidateGlob reports why a glob is not valid, nil if it is.
func ValidateGlob(pattern string) error {
	_, err := globRegexp(pattern)
	return err
}

// Path reports whether the file at p (slash-separated, relative to the project
// root) is left out. Generated files are recognised by content: see Generated.
func (e Excluder) Path(p string) bool {
	if matchesAny(e.exclude, p) {
		return true
	}
	if e.cfg.NoDefaults || matchesAny(e.include, p) {
		return false
	}
	return defaultExcluded(p)
}

// ShellPatterns are `case` patterns for the paths the defaults leave out, for a
// provider script to skip before measuring. Nil when the defaults are off or
// can be overridden, as the script cannot know which paths are rescued; the
// paths are then filtered after measuring.
func (e Excluder) ShellPatterns() []string {
	if e.cfg.NoDefaults || len(e.cfg.Include) > 0 {
		return nil
	}
	var out []string
	for _, d := range defaultExcludedDirs() {
		out = append(out, d+"/*", "*/"+d+"/*")
	}
	for _, f := range defaultExcludedFiles() {
		out = append(out, f, "*/"+f)
	}
	return out
}

func defaultExcluded(p string) bool {
	dir, base := path.Split(p)
	for seg := range strings.SplitSeq(dir, "/") {
		for _, d := range defaultExcludedDirs() {
			if seg == d {
				return true
			}
		}
	}
	for _, f := range defaultExcludedFiles() {
		if ok, _ := path.Match(f, base); ok {
			return true
		}
	}
	return false
}

// Generated reports whether content carries a generated-file marker in its
// first lines.
func Generated(content []byte) bool {
	for _, line := range lineRange(content, 1, generatedLines) {
		line = strings.ToLower(line)
		for _, m := range generatedMarkers() {
			if strings.Contains(line, m) {
				return true
			}
		}
	}
	return false
}

func matchesAny(res []*regexp.Regexp, p string) bool {
	for _, re := range res {
		if re.MatchString(p) {
			return true
		}
	}
	return false
}

func compileGlobs(globs []string) ([]*regexp.Regexp, error) {
	out := make([]*regexp.Regexp, 0, len(globs))
	for _, g := range globs {
		re, err := globRegexp(g)
		if err != nil {
			return nil, err
		}
		out = append(out, re)
	}
	return out, nil
}

// globRegexp turns a glob into a regexp over slash-separated paths: * and ? do
// not cross a slash, ** does, and a pattern ending in / covers everything under
// that directory.
func globRegexp(glob string) (*regexp.Regexp, error) {
	if strings.TrimSpace(glob) == "" {
		return nil, fmt.Errorf("an empty glob")
	}
	glob = strings.TrimPrefix(glob, "./")
	if strings.HasSuffix(glob, "/") {
		glob += "**"
	}
	var b strings.Builder
	b.WriteString("^")
	for i := 0; i < len(glob); i++ {
		switch c := glob[i]; {
		case c == '*' && strings.HasPrefix(glob[i:], "**/"):
			b.WriteString("(?:.*/)?")
			i += 2
		case c == '*' && strings.HasPrefix(glob[i:], "**"):
			b.WriteString(".*")
			i++
		case c == '*':
			b.WriteString("[^/]*")
		case c == '?':
			b.WriteString("[^/]")
		default:
			b.WriteString(regexp.QuoteMeta(string(c)))
		}
	}
	b.WriteString("$")
	re, err := regexp.Compile(b.String())
	if err != nil {
		return nil, fmt.Errorf("glob %q: %w", glob, err)
	}
	return re, nil
}
